            :features="{ sorting: true, filtering: false, selection: false, bulkActions: false, rowActions: false, pagination: false }"
            @update:sorting="handleColumnSort"
            @update:pagination="(payload) => {
              pagination.page = payload.page;
              pagination.rowsPerPage = payload.rowsPerPage;
            }"
            @row-click="(payload) => onRowClick(null, payload.row, payload.rowIndex)"
          >
            <!-- Timestamp Column -->
            <template #body-cell-timestamp="{ row }">
              <div class="timestamp-cell">
                <div class="timestamp-absolute text-weight-medium">
                  {{ formatAbsoluteTime(row.timestamp) }}
                </div>
              </div>
            </template>

            <!-- Severity Column -->
            <template #body-cell-level="{ row }">
              <q-badge
                :color="getSeverityColor(row.level)"
                :label="row.level"
                class="severity-badge"
              />
            </template>

            <!-- Component Column -->
            <template #body-cell-module="{ row }">
              <div class="component-cell">
                <q-icon
                  :name="getModuleIcon(getDisplayModule(row))"
                  size="18px"
                  class="q-mr-xs"
                />
                <span>{{ getDisplayModule(row) }}</span>
              </div>
            </template>

            <!-- Message Column -->
            <template #body-cell-message="{ row }">
              <div class="message-cell">
                <div class="message-text row items-center q-gutter-xs">
                  <span>{{ truncateMessage(getDisplayMessage(row)) }}</span>
                  <q-badge
                    v-if="hasStructuredLog(row)"
                    color="info"
                    label="S"
                    size="xs"
                    class="q-px-xs"
                    style="font-size: 9px;"
                  >
                    <q-tooltip>Structured Log</q-tooltip>
                  </q-badge>
                </div>
              </div>
            </template>

            <!-- No Data Slot -->
            <template #no-data>
              <div class="full-width row flex-center text-grey-7 q-pa-xl">
                <div class="text-center">
                  <q-icon name="inbox" size="64px" color="grey-5" />
                  <div class="text-h6 q-mt-md">
                    {{ $t('no_log_found') }}
                  </div>
                  <div class="text-body2 q-mt-sm">
                    {{ $t('adjust_filters') }}
                  </div>
                </div>
              </div>
            </template>
          </DocBitsTable>
        </q-card>
      </div>

      <!-- Pagination Navigation -->
      <div v-if="displayedLogs.length > 0" class="pagination-section q-pa-md">
        <q-card flat bordered>
          <q-card-section class="row items-center justify-between">
            <!-- Page Info -->
            <div class="text-body2 text-grey-7">
              Page {{ currentPage }} of {{ totalPages > 0 ? totalPages : '?' }}
              <span v-if="pagination.rowsNumber > 0">
                ({{ pagination.rowsNumber }} total logs)
              </span>
            </div>

            <!-- Navigation Buttons -->
            <div class="row q-gutter-sm">
              <q-btn
                outline
                color="primary"
                icon="chevron_left"
                label="Previous"
                :disable="!hasPreviousPage || loading"
                @click="goToPreviousPage"
                data-cy="prev-page-btn"
              />

              <q-btn
                outline
                color="primary"
                icon-right="chevron_right"
                label="Next"
                :disable="!hasNextPage || loading"
                @click="goToNextPage"
                data-cy="next-page-btn"
              />
            </div>
          </q-card-section>
        </q-card>
      </div>

      <!-- Auto Refresh Toggle -->
      <div class="refresh-section q-pa-md">
        <q-card flat bordered>
          <q-card-section class="row items-center justify-between">
            <div class="row items-center q-gutter-sm">
              <f-toggle size="xs"
                v-model="autoRefresh"
                label="Auto-refresh"
                color="primary"
                @update:model-value="toggleAutoRefresh"
              />
              <span v-if="autoRefresh" class="text-caption text-grey-7">
                (every 30 seconds)
              </span>
            </div>
            <div>
              <q-btn
                outline
                color="primary"
                icon="refresh"
                label="Refresh Now"
                @click="loadLogs"
                :loading="loading"
              />
              <q-btn
                outline
                color="primary"
                icon="download"
                label="Export JSON"
                class="q-ml-sm"
                @click="exportLogs"
              />
              <q-btn
                outline
                color="primary"
                icon="folder_zip"
                label="Download Logs"
                class="q-ml-sm"
                :loading="isDownloading"
