                    />
                    <span class="text-caption text-grey-7">
                      {{ formatDistanceToNow(new Date(exportItem.created_at), { addSuffix: true }) }}
                    </span>
                  </q-item-label>
                  <q-item-label caption>
                    <span v-if="exportItem.log_count">
                      {{ exportItem.log_count.toLocaleString() }} logs
                    </span>
                    <span v-if="exportItem.file_size_bytes" class="q-ml-sm">
                      ({{ formatFileSize(exportItem.file_size_bytes) }})
                    </span>
                    <span v-if="exportItem.expires_at && exportItem.status === 'ready'" class="q-ml-sm">
                      • Expires {{ formatDistanceToNow(new Date(exportItem.expires_at), { addSuffix: true }) }}
                    </span>
                    <span v-if="exportItem.error_message" class="text-negative">
                      {{ exportItem.error_message }}
                    </span>
                  </q-item-label>
                </q-item-section>

                <q-item-section side>
                  <div class="row q-gutter-sm">
