                      @click="downloadExport(exportItem)"
                    >
                      <q-tooltip>Download ZIP</q-tooltip>
                    </q-btn>
                    <q-btn
                      flat
                      round
                      color="negative"
                      icon="delete"
                      @click="deleteExport(exportItem)"
                    >
                      <q-tooltip>Delete</q-tooltip>
                    </q-btn>
                  </div>
