</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { formatDistanceToNow, format, parseISO } from 'date-fns';
import { activityLogsApiService } from 'src/services';
import type { LogExportStatusResponse } from 'src/services/activityLogs/ActivityLogsApiService';
import { useQuasar } from 'quasar';
// JSZip removed - using backend export API instead
import DocBitsTable from '@/components/Table/DocBitsTable.vue';
import { useTranslate } from '@tolgee/vue';

const { t } = useTranslate();

const $q = useQuasar();
const router = useRouter();
const route = useRoute();

// UI state
const logsSection = ref<HTMLElement | null>(null);

// Data state
const loading = ref(false);
const metricsLoading = ref(false);
const logs = ref<any[]>([]);
const displayedLogs = ref<any[]>([]);
const selectedTimePreset = ref('today');
const customStartDate = ref('');
const customEndDate = ref('');
const selectedSeverities = ref<string[]>(['ERROR', 'WARN', 'INFO', 'DEBUG']);
const selectedServices = ref<string[]>([]);
const searchTerm = ref('');
const autoRefresh = ref(false);
const autoRefreshInterval = ref<any>(null);

// Statistics
const logStats = ref({
  total: 0,
  error: 0,
  warn: 0,
  info: 0,
  debug: 0,
  topSource: { name: '-', count: 0 },
  peakTime: { time: '-', count: 0 },
});

// Pagination
const pagination = ref({
  sortBy: 'timestamp',
  descending: true,
  page: 1,
  rowsPerPage: 50,
  rowsNumber: 0,
});

// URL-backed pagination state
const currentPage = ref(1);
const pageSize = ref(50);
const hoursPerPage = ref(1);
const hasNextPage = ref(false);
const hasPreviousPage = ref(false);
const totalPages = ref(0);

// Time Range Presets
const timePresetOptions = computed(() => {
  // Calculate hours since midnight in user's browser timezone for "Today" filter
  const now = new Date();
  const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
  const hoursSinceMidnight = Math.max(1, Math.ceil((now.getTime() - midnight.getTime()) / (1000 * 60 * 60)));

  return [
    {
      label: t.value('last_hour'),
      value: 'last_hour',
      hours: 1,
    },
    { label: t.value('today'), value: 'today', hours: hoursSinceMidnight },
    {
      label: t.value('last_7_days'),
      value: 'last_7_days',
      hours: 168,
    },
    {
      label: t.value('last_30_days'),
      value: 'last_30_days',
      hours: 720,
    },
    { label: t.value('custom'), value: 'custom', hours: 0 },
  ];
});

// Severity Options
const severityOptions = computed(() => [
  { label: 'Debug', value: 'DEBUG', color: 'grey-7', icon: 'bug_report' },
  { label: 'Info', value: 'INFO', color: 'primary', icon: 'info' },
  { label: 'Warning', value: 'WARN', color: 'warning', icon: 'warning' },
  { label: 'Error', value: 'ERROR', color: 'negative', icon: 'error' },
]);

// Service Options - Dynamic Loading
const servicesLoading = ref(false);
const servicesError = ref<string | null>(null);
const availableServices = ref<Array<{ name: string; description: string }>>([]);

/**
 * Initialize component state from URL query parameters
 */
const initializeFromUrl = () => {
  const query = route.query;

  // Parse with validation and defaults
  currentPage.value = Math.max(1, parseInt(String(query.page || '1'), 10));
  pageSize.value = Math.min(Math.max(1, parseInt(String(query.page_size || '50'), 10)), 1000);
  hoursPerPage.value = Math.min(Math.max(1, parseInt(String(query.hours_per_page || '1'), 10)), 168);

  // Parse log levels
  if (query.log_level) {
    const levels = String(query.log_level).split(',').map(l => l.trim().toUpperCase());
    const valid = levels.filter(l => ['ERROR', 'WARN', 'INFO', 'DEBUG'].includes(l));
    if (valid.length > 0) {
      selectedSeverities.value = valid;
    }
  }

  // Parse services
  if (query.services) {
    selectedServices.value = String(query.services).split(',').map(s => s.trim());
  }

  // Parse search term
  if (query.search) {
    searchTerm.value = String(query.search);
  }

  // Parse time preset
  if (query.time_preset) {
    const preset = String(query.time_preset);
    const validPresets = ['last_hour', 'today', 'last_7_days', 'last_30_days', 'custom'];
    if (validPresets.includes(preset)) {
      selectedTimePreset.value = preset;
    }
  }

  // Parse custom date range
  if (query.start_date) {
    customStartDate.value = String(query.start_date);
  }
  if (query.end_date) {
    customEndDate.value = String(query.end_date);
  }

  console.log('[ACTIVITY LOGS] Initialized from URL:', {
    page: currentPage.value,
    pageSize: pageSize.value,
    hoursPerPage: hoursPerPage.value,
    severities: selectedSeverities.value,
    services: selectedServices.value,
    search: searchTerm.value,
    timePreset: selectedTimePreset.value,
    customStartDate: customStartDate.value,
    customEndDate: customEndDate.value,
  });
};

/**
 * Update URL query parameters without adding to browser history
 */
const updateUrlParams = () => {
  const query: Record<string, string> = {
    page: String(currentPage.value),
    page_size: String(pageSize.value),
    hours_per_page: String(hoursPerPage.value),
  };

  // Include time preset (only if not default 'today')
  if (selectedTimePreset.value && selectedTimePreset.value !== 'today') {
    query.time_preset = selectedTimePreset.value;
  }

  // Include custom date range if preset is 'custom'
  if (selectedTimePreset.value === 'custom') {
    if (customStartDate.value) {
      query.start_date = customStartDate.value;
    }
    if (customEndDate.value) {
      query.end_date = customEndDate.value;
    }
  }

  // Include non-default filters
  if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
    query.log_level = selectedSeverities.value.join(',');
  }

  if (selectedServices.value.length > 0) {
    query.services = selectedServices.value.join(',');
  }

  if (searchTerm.value?.trim()) {
    query.search = searchTerm.value.trim();
  }

  // Use replace() to avoid cluttering browser history
  router.replace({ path: route.path, query }).catch(err => {
    // Ignore NavigationDuplicated errors
    if (err.name !== 'NavigationDuplicated') {
      console.error('[ACTIVITY LOGS] URL update error:', err);
    }
  });

  console.log('[ACTIVITY LOGS] Updated URL:', query);
};

const SERVICE_DISPLAY_NAMES: Record<string, string> = {
  'api': 'API',
  'api-celery': 'API',
  'api-beats': 'API',
  'api-kafka': 'API',
  'docflow-celery': 'DocFlow',
};

const serviceOptions = computed(() => {
  return availableServices.value.map((service) => ({
    label: SERVICE_DISPLAY_NAMES[service.name.toLowerCase()] ?? service.name.toUpperCase(),
    value: service.name,
    description: service.description,
  }));
});

const loadAvailableServices = async () => {
  try {
    servicesLoading.value = true;
    servicesError.value = null;

    availableServices.value = await activityLogsApiService.fetchAvailableServices();

    console.log('[ACTIVITY LOGS] Loaded services:', availableServices.value);
  } catch (error) {
    console.error('[ACTIVITY LOGS] Failed to load services:', error);
    servicesError.value = 'Failed to load available services';

    // Use fallback services
    availableServices.value = activityLogsApiService.getDefaultServices();
  } finally {
    servicesLoading.value = false;
  }
};

// Table Columns
const columns = computed(() => [
  {
    name: 'timestamp',
    label: t.value('timestamp'),
    field: 'timestamp',
    align: 'left' as const,
    sortable: true,
    style: 'width: 180px; max-width: 180px;',
  },
  {
    name: 'level',
    label: t.value('severity'),
    field: 'level',
    align: 'center' as const,
    sortable: true,
    style: 'width: 100px; max-width: 100px;',
  },
  {
    name: 'module',
    label: t.value('component'),
    field: 'module',
    align: 'left' as const,
    sortable: true,
    style: 'width: 150px; max-width: 150px;',
  },
  {
    name: 'message',
    label: t.value('message'),
    field: 'message',
    align: 'left' as const,
    sortable: true,
    style: 'min-width: 300px;',
  },
]);

// Methods

/**
 * Handle column sort change from ColumnOrderBy component
 * Updates pagination state and re-filters logs to apply sorting
 */
const handleColumnSort = (event: { column: string; direction: 'asc' | 'desc' }) => {
  pagination.value.sortBy = event.column;
  pagination.value.descending = event.direction === 'desc';
  filterLogs(); // Re-sort the displayed logs
};

const applyTimePreset = () => {
  if (selectedTimePreset.value !== 'custom') {
    loadLogs();
  }
};

const applyCustomDateRange = () => {
  if (customStartDate.value && customEndDate.value) {
    loadLogs();
  }
};

const toggleSeverity = (severity: string) => {
  // Use immutable operations to avoid need for deep watcher
  if (selectedSeverities.value.includes(severity)) {
    // Immutable removal using filter
    selectedSeverities.value = selectedSeverities.value.filter((s) => s !== severity);
  } else {
    // Immutable addition using spread
    selectedSeverities.value = [...selectedSeverities.value, severity];
  }
  filterLogs();
};

const loadLogs = async () => {
  try {
    loading.value = true;

    // Determine hours based on preset or custom range
    let hours = 1;
    const preset = timePresetOptions.value.find(
      (p) => p.value === selectedTimePreset.value,
    );
    if (preset && preset.value !== 'custom') {
      hours = preset.hours;
    } else if (
      selectedTimePreset.value === 'custom' &&
      customStartDate.value &&
      customEndDate.value
    ) {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build API parameters with time-window pagination
    const params: any = {
      page: currentPage.value, // Dynamic from URL/state
      page_size: pageSize.value, // Dynamic from URL/state
      hours, // Pass the full hours value based on selected time preset
    };

    // Add severity filter
    if (
      selectedSeverities.value.length > 0 &&
      selectedSeverities.value.length < 4
    ) {
      params.log_level = selectedSeverities.value.join(',');
    }

    // Add service filter
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    // Fetch logs and metrics in parallel
    const [logsResponse] = await Promise.all([
      activityLogsApiService.getOrganizationLogs(params),
      loadMetrics(), // Load metrics separately for better performance
    ]);

    logs.value = logsResponse.logs || [];

    // Apply client-side filtering
    filterLogs();

    // Update pagination metadata from API response
    // The API returns pagination info which may not be typed yet
    const apiResponse = logsResponse as any;
    if (apiResponse.pagination) {
      // If backend returns full pagination metadata
      pagination.value.rowsNumber = apiResponse.pagination.total_entries || 0;
      hasNextPage.value = apiResponse.pagination.has_next_page || false;
      hasPreviousPage.value = apiResponse.pagination.has_previous_page || false;
      totalPages.value = apiResponse.pagination.total_pages || 0;
    } else {
      // Fallback: Calculate pagination based on response
      pagination.value.rowsNumber = logsResponse.total_entries || 0;
      const totalEntries = logsResponse.total_entries || 0;
      totalPages.value = Math.ceil(totalEntries / pageSize.value);
      hasNextPage.value = currentPage.value < totalPages.value;
      hasPreviousPage.value = currentPage.value > 1;
    }

    console.log('[ACTIVITY LOGS] Loaded logs:', {
      total: logs.value.length,
      params,
      response: logsResponse,
    });
  } catch (error) {
    console.error('[ACTIVITY LOGS] Error loading logs:', error);
    notify.error(t.value('error_loading'), error instanceof Error ? error.message : 'Unknown error');
  } finally {
    loading.value = false;
  }
};

/**
 * Navigate to next page
 */
const goToNextPage = () => {
  if (hasNextPage.value && !loading.value) {
    currentPage.value++;
    updateUrlParams();
    loadLogs();
  }
};

/**
 * Navigate to previous page
 */
const goToPreviousPage = () => {
  if (hasPreviousPage.value && currentPage.value > 1 && !loading.value) {
    currentPage.value--;
    updateUrlParams();
    loadLogs();
  }
};

/**
 * Reset to first page (called when filters change)
 */
const resetToFirstPage = () => {
  if (currentPage.value !== 1) {
    currentPage.value = 1;
    updateUrlParams();
  }
};

/**
 * Load organization logs metrics (severity counts)
 * Called separately from loadOrganizationLogs for faster metrics display
 */
const loadMetrics = async () => {
  if (metricsLoading.value) return;

  metricsLoading.value = true;

  try {
    // Calculate time range for metrics query
    let hours = 1;
    if (selectedTimePreset.value === 'last_hour') {
      hours = 1;
    } else if (selectedTimePreset.value === 'today') {
      hours = 24;
    } else if (selectedTimePreset.value === 'last_7_days') {
      hours = 168;
    } else if (selectedTimePreset.value === 'last_30_days') {
      hours = 720; // 30 days = 720 hours (will be capped at 24 by backend)
    } else if (selectedTimePreset.value === 'custom') {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build metrics API parameters
    const params: any = {
      hours_per_page: hours, // Send actual hours from time range selection
    };

    // Add severity filter
    if (
      selectedSeverities.value.length > 0 &&
      selectedSeverities.value.length < 4
    ) {
      params.log_level = selectedSeverities.value.join(',');
    }

    // Add service filter
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    // Fetch metrics
    const response = await activityLogsApiService.getOrganizationMetrics(params);

    // API returns counts in nested severity_counts object
    const errorCount = response.severity_counts?.error_count ?? 0;
    const warningCount = response.severity_counts?.warning_count ?? 0;
    const infoCount = response.severity_counts?.info_count ?? 0;
    const debugCount = response.severity_counts?.debug_count ?? 0;
    const totalCount = response.severity_counts?.total ?? 0;

    // Extract peak activity and top source from response
    const peakActivity = response.peak_activity || { time: '-', count: 0 };
    const topSource = response.top_source || { name: '-', count: 0 };

    // Update stats with API response
    logStats.value = {
      total: totalCount || 0,
      error: errorCount || 0,
      warn: warningCount || 0,
      info: infoCount || 0,
      debug: debugCount || 0,
      topSource: topSource,
      peakTime: peakActivity,
    };

    console.log('[ACTIVITY LOGS] Loaded metrics:', {
      params,
      response,
      stats: logStats.value,
    });
  } catch (error) {
    console.error('[ACTIVITY LOGS] Error loading metrics:', error);
    // Don't show error notification for metrics - logs still work
    // Metrics will show 0 if this fails
  } finally {
    metricsLoading.value = false;
  }
};

const filterLogs = () => {
  let filtered = [...logs.value];

  // Filter by severity
  if (selectedSeverities.value.length < 4) {
    filtered = filtered.filter((log) =>
      selectedSeverities.value.includes(log.level),
    );
  }

  // Filter by service (defense-in-depth - backend should also filter)
  if (selectedServices.value.length > 0) {
    filtered = filtered.filter((log) =>
      selectedServices.value.includes(log.module),
    );
  }

  // Filter by search term
  if (searchTerm.value) {
    const search = searchTerm.value.toLowerCase();
    filtered = filtered.filter((log) => {
      // 1. Check basic fields (Message, Module, Organization)
      if (
        log.message?.toLowerCase().includes(search) ||
        log.module?.toLowerCase().includes(search) ||
        log.organization_name?.toLowerCase().includes(search)
      ) {
        return true;
      }

      // 2. Check Metadata
      if (log.metadata) {
        const metadataStr = JSON.stringify(log.metadata).toLowerCase();
        if (metadataStr.includes(search)) return true;
      }

      // 3. Check Structured Log content (often contains the real error details)
      if (log.log) {
        const logContent =
          typeof log.log === 'string'
            ? log.log.toLowerCase()
            : JSON.stringify(log.log).toLowerCase();
        if (logContent.includes(search)) return true;
      }

      return false;
    });
  }

  // Apply sorting based on pagination state
  if (pagination.value.sortBy) {
    filtered.sort((a, b) => {
      let aVal = a[pagination.value.sortBy];
      let bVal = b[pagination.value.sortBy];

      // Handle null/undefined values
      if (aVal == null && bVal == null) return 0;
      if (aVal == null) return pagination.value.descending ? -1 : 1;
      if (bVal == null) return pagination.value.descending ? 1 : -1;

      // Handle numeric comparison
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return pagination.value.descending ? bVal - aVal : aVal - bVal;
      }

      // Handle string comparison
      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comparison = aVal.localeCompare(bVal);
        return pagination.value.descending ? -comparison : comparison;
      }

      // Handle date comparison
      if (pagination.value.sortBy === 'timestamp') {
        const aTime = new Date(aVal).getTime();
        const bTime = new Date(bVal).getTime();
        return pagination.value.descending ? bTime - aTime : aTime - bTime;
      }

      // Default fallback
      return 0;
    });
  }

  displayedLogs.value = filtered;
  pagination.value.rowsNumber = filtered.length;

  // Fallback: If API metrics returned 0 total but we have logs, calculate from client data
  // This ensures charts and badges work even if the metrics endpoint is lagging or empty
  if (logStats.value.total === 0 && logs.value.length > 0) {
    calculateStats(logs.value);
  }
};

const calculateStats = (logsToCount = logs.value) => {
  logStats.value = {
    total: logsToCount.length,
    error: logsToCount.filter((log) => log.level === 'ERROR').length,
    warn: logsToCount.filter((log) => log.level === 'WARN').length,
    info: logsToCount.filter((log) => log.level === 'INFO').length,
    debug: logsToCount.filter((log) => log.level === 'DEBUG').length,
    topSource: logStats.value.topSource || { name: '-', count: 0 },
    peakTime: logStats.value.peakTime || { time: '-', count: 0 },
  };
};

/**
 * Parse timestamp in both formats: ISO 8601 strings or epoch milliseconds
 * Handles backend format change from ISO strings to epoch milliseconds
 */
const parseTimestamp = (timestamp: string | number): Date => {
  if (typeof timestamp === 'number') {
    return new Date(timestamp);
  }
  // Try to parse as number (epoch ms) if string is numeric
  const asNumber = Number(timestamp);
  if (!isNaN(asNumber) && asNumber > 0) {
    return new Date(asNumber);
  }
  // Fall back to ISO parsing
  return parseISO(timestamp);
};

const formatRelativeTime = (timestamp: string | number): string => {
  try {
    return formatDistanceToNow(parseTimestamp(timestamp), { addSuffix: true });
  } catch (error) {
    return String(timestamp);
  }
};

const formatAbsoluteTime = (timestamp: string | number): string => {
  try {
    return format(parseTimestamp(timestamp), 'MMM dd, yyyy HH:mm:ss');
  } catch (error) {
    return String(timestamp);
  }
};

const getSeverityColor = (severity: string): string => {
  const colors: Record<string, string> = {
    ERROR: 'negative',
    WARN: 'warning',
    INFO: 'primary',
    DEBUG: 'grey-7',
  };
  return colors[severity] || 'grey';
};

const getDisplayModule = (row: any): string => {
  return row.module || row.service || 'System';
};

const getModuleIcon = (module: string | null | undefined): string => {
  if (!module) return 'settings';
  
  const icons: Record<string, string> = {
    ocr: 'visibility',
    classification: 'category',
    field_extraction: 'text_fields',
    table_extraction: 'table_chart',
    api: 'api',
    auth: 'lock',
    export: 'file_upload',
    workflow: 'account_tree',
    notification: 'notifications',
    storage: 'storage',
    webhook: 'webhook',
    integration: 'integration_instructions',
    system: 'dns',
  };
  return icons[module.toLowerCase()] || 'settings';
};

const truncateMessage = (message: string, maxLength = 200): string => {
  if (message.length <= maxLength) return message;
  return message.substring(0, maxLength) + '...';
};

/**
 * Check if a string is valid JSON
 */
const isJsonString = (str: string): boolean => {
  try {
    const parsed = JSON.parse(str);
    return typeof parsed === 'object' && parsed !== null;
  } catch {
    return false;
  }
};

/**
 * Format JSON string with proper indentation
 */
const formatJson = (str: string): string => {
  try {
    const parsed = JSON.parse(str);
    return JSON.stringify(parsed, null, 2);
  } catch {
    return str;
  }
};

/**
 * Get formatted message for display
 * Detects JSON and formats it nicely
 */
const getFormattedMessage = (message: string): string => {
  if (isJsonString(message)) {
    return formatJson(message);
  }
  return message;
};

/**
 * Copy text to clipboard
 */
const copyToClipboard = async (text: string) => {
  try {
    await navigator.clipboard.writeText(text);
    notify.success('Copied to clipboard', { duration: 1500 });
  } catch (error) {
    console.error('Failed to copy:', error);
    notify.error('Failed to copy to clipboard');
  }
};

/**
 * Extract and parse the 'log' field from a log entry
 * Many log entries have a 'log' field containing the actual structured log message
 */
const getStructuredLog = (row: any): any | null => {
  if (!row.log) return null;

  try {
    // The 'log' field is typically a JSON string
    if (typeof row.log === 'string') {
      return JSON.parse(row.log);
    }
    // Or it might already be parsed
    if (typeof row.log === 'object') {
      return row.log;
    }
  } catch (error) {
    console.warn('[ACTIVITY LOGS] Failed to parse log field:', error);
  }

  return null;
};

/**
 * Get the best message to display for a log entry
 * Prioritizes the 'log' field's message over the top-level message
 */
const getDisplayMessage = (row: any): string => {
  const structuredLog = getStructuredLog(row);

  // If we have a structured log with a message, use that
  if (structuredLog && structuredLog.message) {
    return structuredLog.message;
  }

  // Fall back to top-level message
  return row.message || 'No message';
};

/**
 * Get the formatted structured log for display
 * Returns the full structured log as formatted JSON
 */
const getFormattedStructuredLog = (row: any): string => {
  const structuredLog = getStructuredLog(row);

  if (structuredLog) {
    return JSON.stringify(structuredLog, null, 2);
  }

  // Fall back to the raw log field if it exists
  if (row.log) {
    if (typeof row.log === 'string') {
      return formatJson(row.log);
    }
    return JSON.stringify(row.log, null, 2);
  }

  // Last resort: format the message field
  return getFormattedMessage(row.message);
};

/**
 * Attempt to parse known log formats into structured data
 */
const parseLogMessage = (message: string): any | null => {
  // Check for "LEVEL - TIME - LOGGER - STATUS - MESSAGE" pattern
  // Example: INFO - 08:01:02 - helpers.enhanced_auth_logger - ✅ AUTH_SUCCESS - Auth...
  const parts = message.split(' - ');
  if (parts.length >= 4) {
    const [level, time, logger, status, ...rest] = parts;
    // Basic validation to ensure it's likely our format
    if (['INFO', 'ERROR', 'WARN', 'DEBUG'].includes(level) && time.includes(':')) {
      return {
        level,
        time,
        logger,
        status,
        message: rest.join(' - ')
      };
    }
  }
  return null;
};

/**
 * Check if a log entry has a structured log field
 */
const hasStructuredLog = (row: any): boolean => {
  return getStructuredLog(row) !== null;
};

/**
 * Copy the full log entry as JSON (all fields)
 */
const copyFullLogEntry = async (row: any) => {
  try {
    const fullLog = JSON.stringify(row, null, 2);
    await navigator.clipboard.writeText(fullLog);
    notify.success('Full log entry copied to clipboard', { duration: 1500 });
  } catch (error) {
    console.error('Failed to copy full log entry:', error);
    notify.error('Failed to copy log entry');
  }
};

const onRowClick = (event: Event, row: any, index: number) => {
  router.push({
    path: `/settings/event-logs/detail/${row.id}`,
    state: {
      log: JSON.parse(JSON.stringify(row)), // Current log
      logsArray: JSON.parse(JSON.stringify(displayedLogs.value)), // Full list of displayed logs
      logIndex: index, // Index of current log
    }
  });
};

const toggleAutoRefresh = (enabled: boolean) => {
  if (enabled) {
    autoRefreshInterval.value = setInterval(() => {
      loadLogs();
    }, 30000); // 30 seconds
    notify.success('Auto-refresh enabled', { description: 'Logs will refresh every 30 seconds' });
  } else {
    if (autoRefreshInterval.value) {
      clearInterval(autoRefreshInterval.value);
      autoRefreshInterval.value = null;
    }
    notify.info('Auto-refresh disabled');
  }
};

const exportLogs = () => {
  try {
    const dataStr = JSON.stringify(displayedLogs.value, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `activity-logs-${format(new Date(), 'yyyy-MM-dd-HHmmss')}.json`;
    link.click();
    URL.revokeObjectURL(url);

    notify.success('Logs exported successfully');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Export error:', error);
    notify.error('Failed to export logs');
  }
};

/**
 * Backend Log Export State
 * Uses async export API with S3 storage for large exports
 */
const isDownloading = ref(false);
const exportList = ref<LogExportStatusResponse[]>([]);
const exportPollingInterval = ref<ReturnType<typeof setInterval> | null>(null);

/**
 * Request a backend log export
 * Uses async API with S3 storage - handles large exports beyond 5000 limit
 */
const downloadLogsAsZip = async () => {
  isDownloading.value = true;

  try {
    // Calculate time range based on preset
    let timeRangeStart: Date;
    let timeRangeEnd: Date = new Date();

    const preset = timePresetOptions.value.find(p => p.value === selectedTimePreset.value);
    if (selectedTimePreset.value === 'custom' && customStartDate.value && customEndDate.value) {
      timeRangeStart = new Date(customStartDate.value);
      timeRangeEnd = new Date(customEndDate.value);
    } else if (preset) {
      timeRangeStart = new Date(Date.now() - preset.hours * 60 * 60 * 1000);
    } else {
      timeRangeStart = new Date(Date.now() - 24 * 60 * 60 * 1000); // Default 24h
    }

    // Build export request params
    const params: any = {
      time_range_start: timeRangeStart.toISOString(),
      time_range_end: timeRangeEnd.toISOString(),
    };

    if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
      params.log_levels = selectedSeverities.value.join(',');
    }

    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    if (searchTerm.value?.trim()) {
      params.search_query = searchTerm.value.trim();
    }

    console.log('[ACTIVITY LOGS] Requesting export:', params);

    // Request export from backend
    const exportResponse = await activityLogsApiService.requestLogExport(params);

    console.log('[ACTIVITY LOGS] Export requested:', exportResponse);

    notify.success('Export requested', { description: 'Processing in background. Download link will appear when ready.' });

    // Refresh export list and start polling
    await loadExportList();
    startExportPolling();

  } catch (error: any) {
    console.error('[ACTIVITY LOGS] Export request error:', error);

    // Handle rate limit error
    if (error?.response?.status === 429) {
      notify.warning('Export limit reached', { description: 'Maximum 3 pending exports allowed. Wait for current exports to complete.' });
    } else {
      notify.error('Failed to request export', error?.response?.data?.detail || error?.message || 'Unknown error');
    }
  } finally {
    isDownloading.value = false;
  }
};

/**
 * Load list of recent exports for the organization
 */
const loadExportList = async () => {
  try {
    const response = await activityLogsApiService.getLogExportList();
    exportList.value = response.exports || [];
    console.log('[ACTIVITY LOGS] Export list loaded:', exportList.value.length, 'exports');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Failed to load export list:', error);
  }
};

/**
 * Start polling for export status updates
 */
const startExportPolling = () => {
  // Don't start if already polling
  if (exportPollingInterval.value) return;

  // Check if there are any pending/processing exports
  const hasPendingExports = exportList.value.some(
    e => e.status === 'pending' || e.status === 'processing'
  );

  if (!hasPendingExports) return;

  console.log('[ACTIVITY LOGS] Starting export status polling');

  exportPollingInterval.value = setInterval(async () => {
    await loadExportList();

    // Check if any export completed
    const hasPending = exportList.value.some(
      e => e.status === 'pending' || e.status === 'processing'
    );

    // Show notification for newly ready exports
    const readyExports = exportList.value.filter(e => e.status === 'ready' && e.download_available);
    if (readyExports.length > 0) {
      const latestReady = readyExports[0];
      const logCountText = latestReady.log_count ? `${latestReady.log_count.toLocaleString()} logs` : '';
      const fileSizeText = latestReady.file_size_bytes
        ? `${(latestReady.file_size_bytes / 1024 / 1024).toFixed(2)} MB`
        : '';

      notify.success('Export ready for download', { description: [logCountText, fileSizeText].filter(Boolean).join(' • ') });
    }

    // Stop polling if no more pending exports
    if (!hasPending) {
      stopExportPolling();
    }
  }, 10000); // Poll every 10 seconds
};

/**
 * Stop export status polling
 */
const stopExportPolling = () => {
  if (exportPollingInterval.value) {
    console.log('[ACTIVITY LOGS] Stopping export status polling');
    clearInterval(exportPollingInterval.value);
    exportPollingInterval.value = null;
  }
};

/**
 * Download a completed export
 */
const downloadExport = (exportItem: LogExportStatusResponse) => {
  if (!exportItem.download_available) {
    notify.warning('Export not ready', { description: `Current status: ${exportItem.status}` });
    return;
  }

  const downloadUrl = activityLogsApiService.getLogExportDownloadUrl(exportItem.id);

  // Open download in new tab (will trigger file download)
  window.open(downloadUrl, '_blank');

  notify.info('Starting download...');
};

/**
 * Delete/cancel an export
 */
const deleteExport = async (exportItem: LogExportStatusResponse) => {
  try {
    await activityLogsApiService.deleteLogExport(exportItem.id);
    await loadExportList();

    notify.success('Export deleted');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Failed to delete export:', error);
    notify.error('Failed to delete export');
  }
};

/**
 * Format file size in human readable format
 */
const formatFileSize = (bytes: number | undefined): string => {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
};

/**
 * Get status color for export badge
 */
const getExportStatusColor = (status: string): string => {
  const colors: Record<string, string> = {
    pending: 'orange',
    processing: 'blue',
    ready: 'positive',
    failed: 'negative',
    expired: 'grey',
  };
  return colors[status] || 'grey';
};

/**
 * Check if there are any pending/processing exports
 */
const hasPendingExports = computed(() =>
  exportList.value.some(e => e.status === 'pending' || e.status === 'processing')
);

/**
 * Calculate appropriate interval for time series chart based on time range
 *
 * @param hours - Total hours in time range
 * @returns Object with intervalMs and intervalLabel
 */
const calculateChartInterval = (hours: number): { intervalMs: number; intervalLabel: string } => {
  if (hours <= 1) {
    // 1 hour or less: 5-minute intervals
    return { intervalMs: 5 * 60 * 1000, intervalLabel: '5-minute' };
  } else if (hours <= 6) {
    // 6 hours or less: 15-minute intervals
    return { intervalMs: 15 * 60 * 1000, intervalLabel: '15-minute' };
  } else if (hours <= 24) {
    // 24 hours or less: 1-hour intervals
    return { intervalMs: 60 * 60 * 1000, intervalLabel: 'hourly' };
  } else if (hours <= 72) {
    // 3 days or less: 3-hour intervals
    return { intervalMs: 3 * 60 * 60 * 1000, intervalLabel: '3-hour' };
  } else {
    // More than 3 days: 6-hour intervals
    return { intervalMs: 6 * 60 * 60 * 1000, intervalLabel: '6-hour' };
  }
};

// Reload data when time preset changes
watch(selectedTimePreset, () => {
  console.log('[ACTIVITY LOGS] Time preset changed to:', selectedTimePreset.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// No deep: true needed - using immutable operations in toggleSeverity
watch(selectedSeverities, () => {
  console.log('[ACTIVITY LOGS] Severity filters changed:', selectedSeverities.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// No deep: true needed - selectedServices is replaced, not mutated
watch(selectedServices, () => {
  console.log('[ACTIVITY LOGS] Service filters changed:', selectedServices.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// Reload data when custom date range changes
watch([customStartDate, customEndDate], () => {
  if (customStartDate.value && customEndDate.value) {
    console.log('[ACTIVITY LOGS] Custom date range changed:', {
      start: customStartDate.value,
      end: customEndDate.value,
    });
    resetToFirstPage();
    updateUrlParams();
    loadLogs();
  }
});

// Search term watcher with debouncing
let searchTimeout: any;
watch(searchTerm, () => {
  clearTimeout(searchTimeout);
  searchTimeout = setTimeout(() => {
    console.log('[ACTIVITY LOGS] Search term changed:', searchTerm.value);
    resetToFirstPage();
    updateUrlParams();
    loadLogs();
  }, 500);
});

/**
 * Handle browser back/forward button navigation
 */
watch(
  () => route.query,
  (newQuery, oldQuery) => {
    // Prevent infinite loop - skip if query hasn't actually changed
    if (JSON.stringify(newQuery) === JSON.stringify(oldQuery)) {
      return;
    }

    console.log('[ACTIVITY LOGS] Browser navigation detected, reinitializing from URL');
    initializeFromUrl();
    loadLogs();
  },
  { deep: true }
);

// Lifecycle
onMounted(async () => {
  initializeFromUrl(); // Initialize state from URL query parameters first
  await loadAvailableServices(); // Load services
  await Promise.all([
    loadLogs(), // Load logs with state from URL
    loadExportList(), // Load recent exports
  ]);

  // Start polling if there are pending exports
  if (hasPendingExports.value) {
    startExportPolling();
  }
});

onBeforeUnmount(() => {
  if (autoRefreshInterval.value) {
    clearInterval(autoRefreshInterval.value);
  }
  stopExportPolling(); // Stop export polling on unmount
});
</script>

